let check_missing = filter (fun f -> not (exists (fun (g,_) -> g = f) (!loaded_files))) check_files;;
List.iter (fun f -> print_string ("NOT LOADED " ^ f ^ "\n")) check_missing;;
Printf.printf "AXIOMS_COUNT %d\n%!" (List.length (axioms()));;
List.iter (fun th -> print_string ("AXIOM " ^ string_of_term (concl th) ^ "\n")) (axioms());;

(* The headline theorems: no hypotheses, and their conclusions are the        *)
(* statements of src/compiler/proofs/compile_correct_statement.ml.            *)
let check_headline =
  hyp compilerProof_compile_correct = [] &&
  aconv (concl compilerProof_compile_correct) compile_correct_statement &&
  hyp compile_correct_safe_for_space = [] &&
  aconv (concl compile_correct_safe_for_space) compile_correct_safe_for_space_statement;;
Printf.printf "HEADLINE %b\n%!" check_headline;;

(* The ag32 headline theorem: no hypotheses, and its conclusion is the       *)
(* statement of src/compiler/backend/ag32/proofs/                             *)
(* ag32_compile_correct_statement.ml.                                         *)
let check_headline_ag32 =
  hyp ag32_compile_correct = [] &&
  aconv (concl ag32_compile_correct) ag32_compile_correct_statement;;
Printf.printf "HEADLINE_AG32 %b\n%!" check_headline_ag32;;

(* The Pancake headline theorem: no hypotheses, and its conclusion is the   *)
(* statement of src/pancake/proofs/pan_to_target_statement.ml.               *)
let check_headline_pancake =
  hyp pan_to_target_compile_semantics = [] &&
  aconv (concl pan_to_target_compile_semantics) pan_to_target_compile_semantics_statement;;
Printf.printf "HEADLINE_PANCAKE %b\n%!" check_headline_pancake;;

(* The Candle headline theorems: no hypotheses, and their conclusions are   *)
(* the statements of src/candle/standard/semantics/candle_logic_statement.ml. *)
let check_headline_candle =
  hyp proves_sound = [] && aconv (concl proves_sound) proves_sound_statement &&
  hyp extends_consistent = [] && aconv (concl extends_consistent) extends_consistent_statement &&
  hyp hol_consistent = [] && aconv (concl hol_consistent) hol_consistent_statement &&
  hyp hol_light_consistent = [] && aconv (concl hol_light_consistent) hol_light_consistent_statement &&
  true;;
Printf.printf "HEADLINE_CANDLE %b\n%!" check_headline_candle;;

(* The Candle prover headline theorems: no hypotheses, and their           *)
(* conclusions are the statements of src/candle/prover/                   *)
(* candle_prover_statement.ml.                                              *)
let check_headline_candle_prover =
  hyp semantics_thm = [] &&
  aconv (concl semantics_thm) candle_prover_semantics_statement &&
  hyp semantics_thm_strong = [] &&
  aconv (concl semantics_thm_strong) candle_prover_semantics_strong_statement;;
Printf.printf "HEADLINE_CANDLE_PROVER %b\n%!" check_headline_candle_prover;;

print_string (if check_missing = [] && List.length (axioms()) = 3 && check_headline && check_headline_ag32 && check_headline_pancake && check_headline_candle && check_headline_candle_prover
              then "CHECK_OK\n" else "CHECK_FAILED\n");;
